-- Optional Ascension Cultist/Necromancer world dependencies.
-- Requires WOW/Client/Data/patch-ZZZZZ-AscensionClasses.MPQ.
-- Apply after the AzerothCore world database base schema.
-- Generated from class-owned data; SkillCardData is excluded.
-- Creature display IDs use collision-safe 3.3.5 models and packaged source assets.
-- Generated class dependency subset; full snapshot tables must never be imported.
-- Source: jealous-sound/azerothcore-wotlk-coa @ 0487265f863b9c50e7757e1f113169b80505ba8b.
DELIMITER $$
DROP PROCEDURE IF EXISTS `advai_assert_class_ids`$$
CREATE PROCEDURE `advai_assert_class_ids`() BEGIN
IF EXISTS (SELECT 1 FROM `creature_template` WHERE (`entry`=50065 AND `name`<>'Lesser Skeletal Warrior') OR (`entry`=50067 AND `name`<>'Raised Gargoyle') OR (`entry`=50068 AND `name`<>'Abomination') OR (`entry`=50073 AND `name`<>'Ghoul') OR (`entry`=50075 AND `name`<>'Skeletal Mage') OR (`entry`=50076 AND `name`<>'Skeletal Archer') OR (`entry`=50078 AND `name`<>'Skeletal Rogue') OR (`entry`=50096 AND `name`<>'Tentacle of Y\'Shaarj') OR (`entry`=50115 AND `name`<>'Decaying Colossus') OR (`entry`=50132 AND `name`<>'Phylactery') OR (`entry`=50133 AND `name`<>'Muckworm') OR (`entry`=50173 AND `name`<>'Frenzied Ghoul') OR (`entry`=50177 AND `name`<>'Frost Wyrm') OR (`entry`=50261 AND `name`<>'Skeletal Smith') OR (`entry`=50263 AND `name`<>'Faceless Destroyer') OR (`entry`=50272 AND `name`<>'Tentacle of C\'Thun') OR (`entry`=50298 AND `name`<>'Eldritch Ritual') OR (`entry`=50303 AND `name`<>'Rotling') OR (`entry`=50309 AND `name`<>'Bone Wraith') OR (`entry`=50320 AND `name`<>'Tomb King') OR (`entry`=50323 AND `name`<>'Crypt Fiend') OR (`entry`=50385 AND `name`<>'Plaguefather') OR (`entry`=51065 AND `name`<>'Greater Skeletal Warrior') OR (`entry`=51275 AND `name`<>'Rotting Frost Giant') OR (`entry`=397771 AND `name`<>'Manifestation of Y\'Shaarj') OR (`entry`=444914 AND `name`<>'Foul Invocation') OR (`entry`=500464 AND `name`<>'Eldritch Tentacle') OR (`entry`=500465 AND `name`<>'Tentacle of Yogg-Saron') OR (`entry`=500482 AND `name`<>'Gravebound Champion') OR (`entry`=500483 AND `name`<>'Spellbound Champion') OR (`entry`=500484 AND `name`<>'Icebound Champion') OR (`entry`=500650 AND `name`<>'Banshee') OR (`entry`=501464 AND `name`<>'Tentacle of N\'Zoth') OR (`entry`=503030 AND `name`<>'Lesser Zombie') OR (`entry`=503031 AND `name`<>'Zombie') OR (`entry`=503032 AND `name`<>'Greater Zombie') OR (`entry`=503200 AND `name`<>'Bone Construct') OR (`entry`=523032 AND `name`<>'Zombie') OR (`entry`=533030 AND `name`<>'Apocalyptic Skies') OR (`entry`=542064 AND `name`<>'Tombstone') OR (`entry`=542065 AND `name`<>'Risen Ghoul') OR (`entry`=575091 AND `name`<>'Scourge Transporter') OR (`entry`=840025 AND `name`<>'Hallucination')) THEN
SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ADVAI Ascension creature ID conflicts with existing world content';
END IF; END$$
CALL `advai_assert_class_ids`()$$
DROP PROCEDURE `advai_assert_class_ids`$$
